// Tutorial index. The grouped/ordered lesson list is precomputed in the
// `tutorial-data` module (generated by scripts/gen-tutorial.mjs), so this
// controller just hands it to the template — nothing here for the scope scan
// to trip over.
import { controller, type ViewScope } from '@ship/sui-runtime'
import type { Scope } from './page.sui'
import { TUTORIAL_GROUPS } from '../../src/tutorial-data'

export default controller({
  scope: (_ctx: ViewScope<Scope>) => {
    return { groups: TUTORIAL_GROUPS }
  },
})
